import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { cacheLife } from "next/cache";
import { CareerProfile, Meta, type IndexEntry, type KindCode } from "./onet/types";
import { prepareIndex, searchCareers } from "./search";

// Server-side access to the career data generated by scripts/import-onet.ts.

const DATA_DIR = join(process.cwd(), "src/data/onet");
const CODE = /^\d{2}-\d{4}\.\d{2}$/;

export type CareerMatch = {
  code: string;
  title: string;
  description: string;
  jobZone: number;
  highPoint: KindCode | null;
  matchedTitle: string | null;
};

let prepared: Promise<ReturnType<typeof prepareIndex>> | undefined;

function getPreparedIndex() {
  prepared ??= readFile(join(DATA_DIR, "index.json"), "utf8").then((text) =>
    prepareIndex(JSON.parse(text) as IndexEntry[]),
  );
  return prepared;
}

export async function findCareers(query: string, limit = 20): Promise<CareerMatch[]> {
  const results = searchCareers(await getPreparedIndex(), query, limit);
  return results.map(({ entry, matchedTitle }) => ({
    code: entry.code,
    title: entry.title,
    description: entry.description,
    jobZone: entry.jobZone,
    highPoint: entry.highPoint,
    matchedTitle,
  }));
}

export async function getCareerProfile(code: string): Promise<CareerProfile | null> {
  "use cache";
  cacheLife("max");
  if (!CODE.test(code)) return null;
  try {
    const text = await readFile(join(DATA_DIR, "profiles", `${code}.json`), "utf8");
    return CareerProfile.parse(JSON.parse(text));
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  }
}

export async function getOnetMeta(): Promise<Meta> {
  "use cache";
  cacheLife("max");
  return Meta.parse(JSON.parse(await readFile(join(DATA_DIR, "meta.json"), "utf8")));
}
